// Split the users array into individual items for the loop
const users = $input.first().json.users;
return users.map(u => ({ json: u }));

// Format weather data into a readable summary
const weather = $input.first().json;
const city = $('User Config').first().json.city;

const current = weather.list?.[0];
const later = weather.list?.[2]; // ~6h later

if (!current) {
  return [{ json: { weatherText: 'Нет данных о погоде.' } }];
}

const temp = Math.round(current.main.temp);
const feelsLike = Math.round(current.main.feels_like);
const desc = current.weather[0].description;
const wind = Math.round(current.wind.speed);
const humidity = current.main.humidity;

let laterTemp = '';
if (later) {
  laterTemp = `Позже до ${Math.round(later.main.temp)}°C.`;
}

const weatherText = `Сейчас ${temp}°C (ощущается ${feelsLike}°C), ${desc}. ${laterTemp}\nВетер ${wind} м/с, влажность ${humidity}%.`;

return [{ json: { weatherText, city } }];

// Parse RSS XML and filter to last 24 hours, limit 5 headlines
const xml = $input.first().json.data || $input.first().json.body || $input.first().json;
let text = '';
if (typeof xml === 'string') {
  text = xml;
} else if (xml.data) {
  text = xml.data;
} else {
  text = JSON.stringify(xml);
}

// Simple XML parsing for RSS items
const items = [];
const itemRegex = /<item>(.*?)<\/item>/gs;
let match;
while ((match = itemRegex.exec(text)) !== null) {
  const itemXml = match[1];

  const titleMatch = itemXml.match(/<title>(.*?)<\/title>/);
  const pubDateMatch = itemXml.match(/<pubDate>(.*?)<\/pubDate>/);
  const sourceMatch = itemXml.match(/<source[^>]*>(.*?)<\/source>/);

  if (titleMatch) {
    const title = titleMatch[1].replace(/<!\[CDATA\[(.*?)\]\]>/g, '$1').trim();
    const pubDate = pubDateMatch ? new Date(pubDateMatch[1]) : null;
    const source = sourceMatch ? sourceMatch[1].replace(/<!\[CDATA\[(.*?)\]\]>/g, '$1').trim() : '';

    items.push({ title, pubDate, source });
  }
}

// Filter to last 24 hours
const now = new Date();
const oneDayAgo = new Date(now.getTime() - 24 * 60 * 60 * 1000);
const recentItems = items.filter(item => {
  if (!item.pubDate) return true; // include items without date
  return item.pubDate >= oneDayAgo;
});

// Take top 5
const top5 = recentItems.slice(0, 5);

const headlines = top5.map(item => {
  const src = item.source ? ` (${item.source})` : '';
  return `• ${item.title}${src}`;
}).join('\n');

const newsText = top5.length > 0 ? headlines : 'Нет свежих новостей.';

return [{ json: { newsText, newsCount: top5.length } }];

// Combine all data into a single prompt for the AI
const items = $input.all();
const weather = items.find(i => i.json.weatherText) || { json: { weatherText: 'Нет данных.', city: '' } };
const news = items.find(i => i.json.newsText) || { json: { newsText: 'Нет новостей.' } };
const quote = items.find(i => i.json.quoteText) || { json: { quoteText: 'Действуй!', quoteAuthor: '' } };

const userConfig = $('User Config').first().json;

// Get current time in user's timezone
const now = new Date();
let userTimeStr = '';
try {
  userTimeStr = now.toLocaleTimeString('ru-RU', {
    timeZone: userConfig.timezone,
    hour: '2-digit',
    minute: '2-digit',
    hour12: false
  });
} catch(e) {
  userTimeStr = userConfig.sendTime || '07:00';
}

return [{
  json: {
    telegramId: userConfig.telegramId,
    telegramName: userConfig.telegramName,
    userId: userConfig.userId,
    city: userConfig.city || weather.json.city,
    timezone: userConfig.timezone,
    userTime: userTimeStr,
    weatherText: weather.json.weatherText,
    newsText: news.json.newsText,
    quoteText: quote.json.quoteText,
    quoteAuthor: quote.json.quoteAuthor
  }
}];

